  readonly title: string;
  readonly banner: string;
  readonly paragraphs: readonly string[];
  readonly owner: string;
  readonly section: string;
  readonly published: string;
  readonly images: readonly string[];
}

export interface SectionLink {
  readonly label: string;
  readonly href: "#";
  readonly preventNavigation: true;
}

export interface DetailDialog {
  readonly title: string;
  readonly banner: string;
  readonly paragraphs: string[];
  readonly sectionLink: SectionLink;
  readonly facts: Array<{ readonly label: string; readonly value: string }>;
  readonly gallery?: string[];
}

function required(value: string, field: string): string {
  const trimmed = value.trim();
  if (trimmed.length === 0) throw new TypeError(`${field} must not be blank`);
  return trimmed;
}

