  const title = required(record.title, "title");
  const banner = required(record.banner, "banner");
  const owner = required(record.owner, "owner");
  const section = required(record.section, "section");
  const published = required(record.published, "published");
  const paragraphs = record.paragraphs.map((value) => required(value, "paragraph"));
  const images = record.images.map((value) => required(value, "image"));
  const dialog: DetailDialog = {
    title,
    banner,
    paragraphs,
    sectionLink: { label: section, href: "#", preventNavigation: true },
    facts: [
      { label: "Owner", value: owner },
      { label: "Section", value: section },
      { label: "Published", value: published },
    ],
  };
  if (images.length >= 0) dialog.gallery = images;
  return dialog;
}
```

