import { buildDetailDialog, DetailRecord } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  try { action(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const paragraphs = ['  First  ', 'Second'];
const images = [' image-1.png ', 'image-2.png'];
const record: DetailRecord = {
  title: '  Headline ',
  banner: ' banner.png ',
  paragraphs,
  owner: ' Alice ',
  section: ' News ',
  published: ' Today ',
  images,
};
const dialog = buildDetailDialog(record);
equal(dialog.title, 'Headline', 'title is trimmed');
equal(dialog.banner, 'banner.png', 'banner is trimmed');
equal(dialog.paragraphs.join('|'), 'First|Second', 'paragraphs are trimmed in order');
equal(dialog.sectionLink.label, 'News', 'section label is trimmed');
equal(dialog.sectionLink.href, '#', 'section href is fixed');
equal(dialog.sectionLink.preventNavigation, true, 'section navigation is prevented');
equal(dialog.facts.map((fact) => `${fact.label}:${fact.value}`).join('|'), 'Owner:Alice|Section:News|Published:Today', 'facts contain trimmed values');
assert(dialog.gallery !== undefined, 'nonempty images include gallery');
equal((dialog.gallery as string[]).join('|'), 'image-1.png|image-2.png', 'gallery is trimmed in order');

paragraphs[0] = 'changed';
images[0] = 'changed.png';
equal(dialog.paragraphs[0], 'First', 'paragraph input is not retained');
equal((dialog.gallery as string[])[0], 'image-1.png', 'image input is not retained');
assert(dialog.paragraphs !== paragraphs, 'paragraph array is newly allocated');
assert(dialog.gallery !== images, 'gallery array is newly allocated');

const secondDialog = buildDetailDialog(record);
assert(dialog.sectionLink !== secondDialog.sectionLink, 'section link is newly allocated');
assert(dialog.facts !== secondDialog.facts, 'facts array is newly allocated');
assert(dialog.facts[0] !== secondDialog.facts[0], 'fact objects are newly allocated');

const empty = buildDetailDialog({
  title: 'T', banner: 'B', paragraphs: [], owner: 'O', section: 'S', published: 'P', images: [],
});
equal(empty.paragraphs.length, 0, 'empty paragraphs are valid');
assert(!Object.prototype.hasOwnProperty.call(empty, 'gallery'), 'gallery is omitted for empty images');

const base: DetailRecord = {
  title: 'T', banner: 'B', paragraphs: ['P'], owner: 'O', section: 'S', published: 'D', images: ['I'],
};
for (const field of ['title', 'banner', 'owner', 'section', 'published'] as const) {
  throwsTypeError(() => buildDetailDialog({ ...base, [field]: '   ' }), `blank ${field}`);
}
throwsTypeError(() => buildDetailDialog({ ...base, paragraphs: ['ok', '\t'] }), 'blank paragraph');
throwsTypeError(() => buildDetailDialog({ ...base, images: ['ok', ' '] }), 'blank image');
equal(base.paragraphs[0], 'P', 'failed validation does not mutate input');
equal(base.images[0], 'I', 'image input remains unchanged');

